WITH lines AS (SELECT id, plan, effective_from, currency, element FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_prices) t AS element) SELECT CASE WHEN element >= 62 THEN 'HIGH' ELSE 'LOW' END AS element_tier, ROUND(SUM(element) / NULLIF(COUNT(CASE WHEN plan = 'basic' THEN 1 END), 0), 2) AS element_per_basic, COUNT(DISTINCT currency) AS distinct_currencies, ROUND(SUM(element) / NULLIF(COUNT(CASE WHEN currency = 'THB' THEN 1 END), 0), 2) AS element_per_thb, ROUND(AVG(element), 2) AS avg_element, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, SUM(CASE WHEN currency = 'THB' THEN element ELSE 0 END) AS thb_element FROM lines GROUP BY 1 HAVING COUNT(DISTINCT currency) < 1000 ORDER BY thb_element DESC NULLS LAST;
